import { openLocalMedia, type OpenedMedia } from "../lib/mediaSource";
import { getPreferredDriverType } from "../lib/storage";
import type { MediaInfo } from "../types";

const infoCache = new Map<string, Promise<MediaInfo>>();
const mediaWidthCache = new Map<string, string>();
function getInfo(id: string): Promise<MediaInfo> {
  let p = infoCache.get(id);
  if (!p) {
    p = api.mediaInfo(id);
    infoCache.set(id, p);
    p.catch(() => infoCache.delete(id)); // 失敗不快取，之後補上檔案就能恢復
  }
  return p;
}

type State =
  | { status: "loading" }
  | { status: "ok"; info: MediaInfo; src: string }
  | { status: "missing" }
  | { status: "unavailable"; reason: string };

// 電腦版沿用後端網址（行為不變）；iPad／網頁版讀本機 IndexedDB，沒有才從 Drive 下載。null＝確定遺失
async function openMedia(id: string): Promise<OpenedMedia | null> {
  if (getPreferredDriverType() === "dexie") return openLocalMedia(id);
  return getInfo(id).then(
    (info) => ({ info, src: mediaUrl(id), revoke: () => {} }),
    () => null,
  );
}

export function MediaEmbed({
  id,
  explicitWidth,
  onChangeWidth,
  onRemove,
}: {
  id: string;
  explicitWidth?: string;
  onChangeWidth?: (width: string) => void;
  onRemove?: () => void;
}) {
  const [state, setState] = useState<State>({ status: "loading" });
  const [userWidth, setUserWidth] = useState<string | null>(
    () => explicitWidth || mediaWidthCache.get(id) || null,
  );
  const [zoomed, setZoomed] = useState(false);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (!zoomed) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setZoomed(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [zoomed]);

  useEffect(() => {
    if (explicitWidth) {
      mediaWidthCache.set(id, explicitWidth);
      setUserWidth(explicitWidth);
    }
  }, [explicitWidth, id]);

  const changeWidth = (w: string) => {
    mediaWidthCache.set(id, w);
    setUserWidth(w);
    onChangeWidth?.(w);
  };

  useEffect(() => {
    let alive = true;
    let revoke: (() => void) | null = null;
    setState({ status: "loading" });
    openMedia(id).then(
      (m) => {
        if (!alive) {
          m?.revoke();
          return;
        }
        if (!m) {
          setState({ status: "missing" });
          return;
        }
        revoke = m.revoke;
        setState({ status: "ok", info: m.info, src: m.src });
      },
      (e) => {
        console.error(`圖片 ${id} 載入失敗`, e);
        if (alive) setState({ status: "unavailable", reason: e instanceof Error ? e.message : String(e) });
      },
    );
    return () => {
      alive = false;
      revoke?.();
    };
  }, [id, attempt]);

  if (state.status === "loading") return <span className="media-loading">載入中…</span>;
  if (state.status === "unavailable")
    return (
      <span
        className="media-missing"
        role="button"
        tabIndex={0}
        aria-label="圖片尚未下載，點擊重試"
        style={{ cursor: "pointer" }}
        onClick={(e) => {
          e.stopPropagation();
          setAttempt((n) => n + 1);
        }}
      >
        圖片尚未下載（點擊重試）：{state.reason.slice(0, 80)}
      </span>
    );
  if (state.status === "missing")
    return (
      <span className="media-missing" role="img" aria-label="圖片遺失">
        圖片遺失：{id.slice(0, 8)}
      </span>
    );
  const onError = () => {
    infoCache.delete(id);
    setState({ status: "missing" });
  };
  if (state.info.kind === "video")
    return (
      <video
        className="nodrag nowheel"
        style={{ width: userWidth ?? "100%", maxWidth: "100%", borderRadius: 4 }}
        src={state.src}
        controls
        preload="metadata"
        onError={onError}
      />
    );

  return (
    <span
      className="media-embed-wrap"
      style={
        userWidth
          ? { display: "block", width: userWidth, maxWidth: "100%" }
          : { display: "inline-block", maxWidth: "100%" }
      }
    >
      <img
        ref={(el) => {
          if (!el) return;
          el.style.setProperty("width", "100%", "important");
          el.style.setProperty("max-width", "100%", "important");
          el.style.setProperty("max-height", "none", "important");
          el.style.setProperty("height", "auto", "important");
          el.style.setProperty("object-fit", "unset", "important");
          el.style.setProperty("margin", "0", "important");
        }}
        src={state.src}
        alt=""
        loading="lazy"
        onError={onError}
        style={{
          width: "100%",
          maxWidth: "100%",
          maxHeight: "none",
          height: "auto",
          objectFit: "unset",
          margin: 0,
          borderRadius: 4,
          display: "block",
        }}
      />
      <span
        className="media-size-bar nodrag nowheel"
        style={{ display: "inline-flex", gap: 4, marginTop: 3 }}
        onClick={(e) => e.stopPropagation()}
        onDoubleClick={(e) => e.stopPropagation()}
      >
        <button
          type="button"
          style={{
            fontSize: 10,
            padding: "1px 5px",
            opacity: userWidth === "33%" ? 1 : 0.7,
            fontWeight: userWidth === "33%" ? 600 : 400,
            cursor: "pointer",
          }}
          onClick={() => changeWidth("33%")}
        >
          小
        </button>
        <button
          type="button"
          style={{
            fontSize: 10,
            padding: "1px 5px",
            opacity: userWidth === "60%" ? 1 : 0.7,
            fontWeight: userWidth === "60%" ? 600 : 400,
            cursor: "pointer",
          }}
          onClick={() => changeWidth("60%")}
        >
          中
        </button>
        <button
          type="button"
          style={{
            fontSize: 10,
            padding: "1px 5px",
            opacity: userWidth === "100%" ? 1 : 0.7,
            fontWeight: userWidth === "100%" ? 600 : 400,
            cursor: "pointer",
          }}
          onClick={() => changeWidth("100%")}
        >
          滿版
        </button>
        <button
          type="button"
          style={{ fontSize: 10, padding: "1px 5px", opacity: 0.7, cursor: "pointer" }}
          onClick={() => setZoomed(true)}
        >
          🔍 放大
        </button>
        {onRemove && (
          <button
            type="button"
            style={{ fontSize: 10, padding: "1px 5px", opacity: 0.85, color: "#f87171", cursor: "pointer" }}
            onClick={onRemove}
            title="從卡片內文移除此圖片"
          >
            🗑️ 移除
          </button>
        )}
      </span>
      {zoomed &&
        createPortal(
          <div
            className="nodrag nowheel"
            onClick={(e) => {
              e.stopPropagation();
              setZoomed(false);
            }}
            onDoubleClick={(e) => e.stopPropagation()}
            style={{
              position: "fixed",
              inset: 0,
              zIndex: 10000,
              background: "rgba(0, 0, 0, 0.88)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "zoom-out",
            }}
          >
            <img
              src={state.src}
              alt=""
              style={{ width: "96vw", height: "96vh", objectFit: "contain" }}
            />
          </div>,
          document.body,
        )}
    </span>
  );
}

