            onSelectCard={(id) => {
              if (p.onPreviewCard) {
                p.onPreviewCard(id);
                p.onTab("search");
              } else {
                p.onSelectCard(id);
              }
            }}
            onTagsChanged={() => (p.onTagsChanged(), refetch())}
            report={report}
            info={p.info}
          />
        )}
        {activeTab === "relations" && card && (
